UPDATE linkable_accounts
SET is_linked = 1
WHERE id = #{linkableAccountId}

UPDATE bank_accounts
SET is_primary = 1
WHERE id = #{accountId} AND user_id = #{userId}

UPDATE bank_accounts
SET is_deleted = 1
WHERE id = #{accountId} AND user_id = #{userId}

UPDATE linkable_accounts
SET is_linked = 0
WHERE user_id = #{userId}
AND bank_code = #{bankCode}
AND account_number = #{accountNumber}
